for n in range(_sage_const_2 , _sage_const_11 ):
    p27_q[n+_sage_const_1 ] = B_p27(n)/A_p27(n)*p27_q[n] - C_p27(n-_sage_const_1 )/A_p27(n-_sage_const_1 )*p27_q[n-_sage_const_1 ] + D_p27(n-_sage_const_2 )/A_p27(n-_sage_const_2 )*p27_q[n-_sage_const_2 ]

